DO $$
DECLARE v_count int;
BEGIN
  SELECT count(*) INTO v_count FROM operacao_frentes
  WHERE event_id = '5a1da5fb-3115-4ae3-af50-15ce1f869a5c';
  IF v_count <> 19 THEN
