END $$;

-- Verificacao: ja existem etapas neste evento? (evitar duplicar)
DO $$
DECLARE v_count int;
BEGIN
  SELECT count(*) INTO v_count FROM operacao_etapas e
  JOIN operacao_frentes f ON f.id = e.frente_id
  WHERE f.event_id = '5a1da5fb-3115-4ae3-af50-15ce1f869a5c';
  IF v_count > 0 THEN
    RAISE EXCEPTION 'Ja existem % etapas neste evento. Abortado.', v_count;
  END IF;
END $$;

